arguments.argument:
var ind, rand, vind;

ind = ds_list_find_value(list_modpat_sound, global.current_mode*GAS_PATTERN_MAX+global.current_pattern);

//if( global.farting_time > prev_farting_time ){ // 放屁始め
if( obj_gas_generator.emit_particle[global.current_pattern] ){ // 放屁始め
    if( global.fart_sound_pitch )
        global.prev_fart_sound = play_sound(ind, 0.3);
    else
        global.prev_fart_sound = play_sound(ind, 0.0);
      
}else if( global.farting_time > BURST_THRESH && !global.synchro_mode ){ // 連射技の場合
    rand = random(10);
    if(rand < 1.0){
        global.prev_fart_sound = play_sound(ind, 0.5);
    }
}

prev_farting_time = global.farting_time;
